    }
    const responseData = msg.payload?.data || {};
    const commandRequestId = Number(responseData.command_request_id);
    const stopStatus = String(responseData.physical_stop_request_status || '').toUpperCase();
    if (Number.isSafeInteger(commandRequestId) && commandRequestId > 0
        && ['PENDENTE', 'PROCESSANDO'].includes(stopStatus)
        && Number.isInteger(Number(msg.equipmentId)) && msg.traceEquipment) {
        const baseUrl = String(env.get('TRACE_API_URL') || '').replace(/\/$/, '');
        const token = String(msg.traceToken || '');
        if (baseUrl && token) {
            node.send([null, null, { ...msg, url: baseUrl + '/api/plc_gateway.php', method: 'POST',
                headers: { 'X-Device-Token': token, 'Content-Type': 'application/json' },
                payload: { action: 'CLAIM', equipment_id: Number(msg.equipmentId),
                    priority_stop_request_id: commandRequestId } }]);
        }
    }
    const outbox = global.get('traceSensorEventOutbox');
    if (!outbox) {
        scheduleRetry(msg, 'fila local indisponível para confirmação');
        return [null, null, null];
    }
    outbox.acknowledge(eventUuid).then(() => node.send([msg, null, null])).catch(error => {
        msg.statusCode = 0;
        scheduleRetry(msg, error.message);
    });
    return [null, null, null];
}
// Só a recuperação da fila durável marca sensorEventReplay. Passagem antiga que o
// servidor recusa com 422 (fora do período da carga ou dados inválidos) não passa a
// ser aceita depois: vai para a pasta de recusadas e libera a próxima da fila.
// Passagens ao vivo seguem com a retentativa de sempre.
if (msg.sensorEventReplay === true && status === 422 && eventUuid) {
    const outbox = global.get('traceSensorEventOutbox');
    if (outbox && typeof outbox.archive === 'function') {
        const reason = String(msg.payload?.error || '');
        outbox.archive(eventUuid, { status, reason }).then(archived => {
            if (archived) node.warn('Passagem ' + eventUuid + ' do carregamento ' + (event?.carregamento_id || 'desconhecido') + ' recusada na recuperação (HTTP 422' + (reason ? ': ' + reason : '') + '); arquivada fora da fila local.');
        }).catch(error => scheduleRetry(msg, 'não foi possível arquivar: ' + error.message));
        return [null, null, null];
    }
}
scheduleRetry(msg, msg.error?.message || (status ? 'resposta HTTP ' + status : 'sem resposta'));
return [null, null, null];
